-- Update the Privacy Policy detail page content in all four languages.
-- Authoritative source: this migration (applies to the live DB and any fresh DB via migrations).

INSERT INTO public.detail_pages (slug, eyebrow_translations, title_translations, description_translations, subtitle_translations, content_translations, is_visible)
VALUES
  ('privacy',
   '{"en": "Legal", "de": "Rechtliches", "fr": "Juridique", "es": "Legal"}'::jsonb,
   '{"en": "Privacy Policy", "de": "Datenschutzerklärung", "fr": "Politique de confidentialité", "es": "Política de privacidad"}'::jsonb,
   '{"en": "Your privacy matters to us. This Privacy Policy explains how Stratifit collects, uses, stores, and protects personal information when you visit our website or use our digital services.", "de": "Ihre Privatsphäre ist uns wichtig. Diese Datenschutzerklärung erläutert, wie Stratifit personenbezogene Informationen erhebt, verwendet, speichert und schützt, wenn Sie unsere Website besuchen oder unsere digitalen Dienstleistungen nutzen.", "fr": "Votre vie privée est importante pour nous. La présente Politique de confidentialité explique comment Stratifit collecte, utilise, conserve et protège vos informations personnelles lorsque vous visitez notre site web ou utilisez nos services numériques.", "es": "Su privacidad es importante para nosotros. Esta Política de Privacidad explica cómo Stratifit recopila, utiliza, almacena y protege la información personal cuando visita nuestro sitio web o utiliza nuestros servicios digitales."}'::jsonb,
   '{"en": "Last updated: August 29, 2026", "de": "Zuletzt aktualisiert: 29. August 2026", "fr": "Dernière mise à jour : 29 août 2026", "es": "Última actualización: 29 de agosto de 2026"}'::jsonb,
   '[
  {"type": "heading", "icon": "file-text", "text_translations": {"en": "1. Introduction", "de": "1. Einleitung", "fr": "1. Introduction", "es": "1. Introducción"}},
  {"type": "paragraph", "text_translations": {"en": "Stratifit (“we,” “our,” or “us”) is committed to protecting your privacy and handling personal information responsibly.", "de": "Stratifit („wir“, „uns“ oder „unser“) verpflichtet sich zum Schutz Ihrer Privatsphäre und zu einem verantwortungsvollen Umgang mit personenbezogenen Daten.", "fr": "Stratifit (« nous », « notre » ou « nos ») s''engage à protéger votre vie privée et à traiter vos informations personnelles de manière responsable.", "es": "Stratifit («nosotros», «nuestro» o «nos») se compromete a proteger su privacidad y a tratar la información personal de forma responsable."}},
  {"type": "paragraph", "text_translations": {"en": "This Privacy Policy explains how we collect, use, disclose, and protect information when you visit [https://stratifit.com](https://stratifit.com) or use our digital services.", "de": "Diese Datenschutzerklärung erläutert, wie wir Informationen erheben, verwenden, offenlegen und schützen, wenn Sie [https://stratifit.com](https://stratifit.com) besuchen oder unsere digitalen Dienstleistungen nutzen.", "fr": "Cette Politique de confidentialité explique comment nous collectons, utilisons, divulguons et protégeons les informations lorsque vous visitez [https://stratifit.com](https://stratifit.com) ou utilisez nos services numériques.", "es": "Esta Política de Privacidad explica cómo recopilamos, utilizamos, divulgamos y protegemos la información cuando visita [https://stratifit.com](https://stratifit.com) o utiliza nuestros servicios digitales."}},
  {"type": "heading", "icon": "eye", "text_translations": {"en": "2. Information We Collect", "de": "2. Welche Informationen wir erheben", "fr": "2. Informations que nous collectons", "es": "2. Información que recopilamos"}},
  {"type": "subheading", "text_translations": {"en": "Personal Information", "de": "Personenbezogene Daten", "fr": "Informations personnelles", "es": "Información personal"}},
  {"type": "paragraph", "text_translations": {"en": "When you contact us through our website, we may collect information that you voluntarily provide, including:", "de": "Wenn Sie uns über unsere Website kontaktieren, können wir die von Ihnen freiwillig bereitgestellten Informationen erfassen, darunter:", "fr": "Lorsque vous nous contactez via notre site web, nous pouvons collecter les informations que vous fournissez volontairement, notamment :", "es": "Cuando se pone en contacto con nosotros a través de nuestro sitio web, podemos recopilar la información que proporciona voluntariamente, incluyendo:"}},
  {"type": "list", "items": [
    {"text_translations": {"en": "Name", "de": "Name", "fr": "Nom", "es": "Nombre"}},
    {"text_translations": {"en": "Email address", "de": "E-Mail-Adresse", "fr": "Adresse e-mail", "es": "Dirección de correo electrónico"}},
    {"text_translations": {"en": "Phone number", "de": "Telefonnummer", "fr": "Numéro de téléphone", "es": "Número de teléfono"}},
    {"text_translations": {"en": "Company or organization name", "de": "Name des Unternehmens oder der Organisation", "fr": "Nom de l''entreprise ou de l''organisation", "es": "Nombre de la empresa u organización"}},
    {"text_translations": {"en": "Information included in your message", "de": "Angaben in Ihrer Nachricht", "fr": "Informations incluses dans votre message", "es": "Información incluida en su mensaje"}},
    {"text_translations": {"en": "Other information you choose to provide", "de": "Weitere Informationen, die Sie freiwillig bereitstellen", "fr": "Toute autre information que vous choisissez de fournir", "es": "Cualquier otra información que decida proporcionar"}}
  ]},
  {"type": "paragraph", "text_translations": {"en": "We use this information to respond to your inquiries, provide requested services, communicate with you, and manage our business relationship.", "de": "Wir verwenden diese Informationen, um Ihre Anfragen zu beantworten, angeforderte Dienstleistungen bereitzustellen, mit Ihnen zu kommunizieren und unsere Geschäftsbeziehung zu verwalten.", "fr": "Nous utilisons ces informations pour répondre à vos demandes, fournir les services demandés, communiquer avec vous et gérer notre relation commerciale.", "es": "Utilizamos esta información para responder a sus consultas, proporcionar los servicios solicitados, comunicarnos con usted y gestionar nuestra relación comercial."}},
  {"type": "subheading", "text_translations": {"en": "Technical Information", "de": "Technische Informationen", "fr": "Informations techniques", "es": "Información técnica"}},
  {"type": "paragraph", "text_translations": {"en": "When you access our website, certain technical information may be processed as part of operating, securing, and maintaining the website. This may include:", "de": "Beim Besuch unserer Website können bestimmte technische Informationen verarbeitet werden, die für den Betrieb, die Sicherheit und die Wartung der Website erforderlich sind. Dazu können gehören:", "fr": "Lorsque vous accédez à notre site web, certaines informations techniques peuvent être traitées afin d''assurer son fonctionnement, sa sécurité et sa maintenance. Il peut notamment s''agir de :", "es": "Cuando accede a nuestro sitio web, cierta información técnica puede ser procesada como parte del funcionamiento, la seguridad y el mantenimiento del sitio. Esto puede incluir:"}},
  {"type": "list", "items": [
    {"text_translations": {"en": "IP address", "de": "IP-Adresse", "fr": "Adresse IP", "es": "Dirección IP"}},
    {"text_translations": {"en": "Browser and device information", "de": "Browser- und Geräteinformationen", "fr": "Informations relatives au navigateur et à l''appareil", "es": "Información del navegador y dispositivo"}},
    {"text_translations": {"en": "Operating system", "de": "Betriebssystem", "fr": "Système d''exploitation", "es": "Sistema operativo"}},
    {"text_translations": {"en": "Referring URL", "de": "Verweisende URL", "fr": "URL de provenance", "es": "URL de referencia"}},
    {"text_translations": {"en": "Date and time of access", "de": "Datum und Uhrzeit des Zugriffs", "fr": "Date et heure d''accès", "es": "Fecha y hora de acceso"}},
    {"text_translations": {"en": "Technical information relating to your visit", "de": "Technische Informationen über Ihren Besuch", "fr": "Informations techniques relatives à votre visite", "es": "Información técnica relacionada con su visita"}}
  ]},
  {"type": "paragraph", "text_translations": {"en": "Some technical information may be processed by our hosting and infrastructure providers where necessary to operate and secure the website.", "de": "Bestimmte technische Informationen können von unseren Hosting- und Infrastruktur-Anbietern verarbeitet werden, soweit dies für den Betrieb und die Sicherheit der Website erforderlich ist.", "fr": "Certaines informations techniques peuvent être traitées par nos fournisseurs d''hébergement et d''infrastructure lorsque cela est nécessaire au fonctionnement et à la sécurité du site.", "es": "Parte de esta información técnica puede ser procesada por nuestros proveedores de alojamiento e infraestructura cuando sea necesario para operar y proteger el sitio web."}},
  {"type": "subheading", "text_translations": {"en": "Analytics Information", "de": "Analyseinformationen", "fr": "Informations analytiques", "es": "Información analítica"}},
  {"type": "paragraph", "text_translations": {"en": "With your consent where required, we use analytics technologies to understand how visitors use our website and to measure website traffic and performance.", "de": "Soweit Ihre Einwilligung erforderlich ist, verwenden wir Analysetechnologien, um zu verstehen, wie Besucher unsere Website nutzen und um den Website-Traffic sowie die Leistung zu messen.", "fr": "Lorsque votre consentement est requis, nous utilisons des technologies d''analyse pour comprendre comment les visiteurs utilisent notre site web et mesurer son trafic et ses performances.", "es": "Cuando sea necesario obtener su consentimiento, utilizamos tecnologías de análisis para comprender cómo los visitantes utilizan nuestro sitio web y medir el tráfico y el rendimiento."}},
  {"type": "paragraph", "text_translations": {"en": "We use Google Analytics 4 (GA4) for detailed website analytics. Depending on your consent and settings, GA4 may process information such as pages viewed, interactions, device and browser information, approximate geographic information, and other usage data.", "de": "Wir verwenden Google Analytics 4 (GA4) für detaillierte Website-Analysen. Abhängig von Ihrer Einwilligung und Ihren Einstellungen kann GA4 Informationen wie aufgerufene Seiten, Interaktionen, Geräte- und Browserinformationen, ungefähre geografische Informationen und weitere Nutzungsdaten verarbeiten.", "fr": "Nous utilisons Google Analytics 4 (GA4) pour les analyses détaillées du site. Selon votre consentement et vos paramètres, GA4 peut traiter des informations telles que les pages consultées, les interactions, les informations relatives à l''appareil et au navigateur, des informations géographiques approximatives et d''autres données d''utilisation.", "es": "Utilizamos Google Analytics 4 (GA4) para realizar análisis detallados del sitio web. Dependiendo de su consentimiento y configuración, GA4 puede procesar información como páginas visitadas, interacciones, información del dispositivo y navegador, información geográfica aproximada y otros datos de uso."}},
  {"type": "paragraph", "text_translations": {"en": "If you reject Analytics consent, our GA4 tracking is not activated for your visit.", "de": "Wenn Sie der Analyse nicht zustimmen, wird das GA4-Tracking für Ihren Besuch nicht aktiviert.", "fr": "Si vous refusez le consentement aux analyses, le suivi GA4 n''est pas activé lors de votre visite.", "es": "Si rechaza el consentimiento para Analytics, el seguimiento de GA4 no se activa durante su visita."}},
  {"type": "paragraph", "text_translations": {"en": "We also use Vercel Web Analytics to obtain aggregated and privacy-focused information about website usage and performance.", "de": "Wir verwenden außerdem Vercel Web Analytics, um aggregierte und datenschutzorientierte Informationen über die Nutzung und Leistung unserer Website zu erhalten.", "fr": "Nous utilisons également Vercel Web Analytics pour obtenir des informations agrégées et respectueuses de la vie privée sur l''utilisation et les performances du site.", "es": "También utilizamos Vercel Web Analytics para obtener información agregada y orientada a la privacidad sobre el uso y el rendimiento del sitio web."}},
  {"type": "paragraph", "text_translations": {"en": "For more information about cookies and analytics technologies, please see our [Cookie Policy](/cookie-policy).", "de": "Weitere Informationen zu Cookies und Analysetechnologien finden Sie in unserer [Cookie-Richtlinie](/cookie-policy).", "fr": "Pour plus d''informations sur les cookies et les technologies d''analyse, veuillez consulter notre [Politique de cookies](/cookie-policy).", "es": "Para obtener más información sobre las cookies y las tecnologías de análisis, consulte nuestra [Política de Cookies](/cookie-policy)."}},
  {"type": "heading", "icon": "clipboard-check", "text_translations": {"en": "3. How We Use Your Information", "de": "3. Wie wir Ihre Informationen verwenden", "fr": "3. Comment nous utilisons vos informations", "es": "3. Cómo utilizamos su información"}},
  {"type": "paragraph", "text_translations": {"en": "We may use information for the following purposes:", "de": "Wir können Informationen für folgende Zwecke verwenden:", "fr": "Nous pouvons utiliser les informations pour :", "es": "Podemos utilizar la información para:"}},
  {"type": "list", "items": [
    {"text_translations": {"en": "To respond to inquiries and contact requests", "de": "Beantwortung von Anfragen und Kontaktanfragen", "fr": "Répondre aux demandes et aux messages de contact", "es": "Responder a consultas y solicitudes de contacto"}},
    {"text_translations": {"en": "To provide and manage our services", "de": "Bereitstellung und Verwaltung unserer Dienstleistungen", "fr": "Fournir et gérer nos services", "es": "Proporcionar y gestionar nuestros servicios"}},
    {"text_translations": {"en": "To communicate with you about our services", "de": "Kommunikation über unsere Dienstleistungen", "fr": "Communiquer avec vous concernant nos services", "es": "Comunicarnos con usted sobre nuestros servicios"}},
    {"text_translations": {"en": "To improve our website, services, and user experience", "de": "Verbesserung unserer Website, Dienstleistungen und Nutzererfahrung", "fr": "Améliorer notre site web, nos services et l''expérience utilisateur", "es": "Mejorar nuestro sitio web, servicios y experiencia del usuario"}},
    {"text_translations": {"en": "To understand website traffic and usage", "de": "Analyse des Website-Traffics und der Nutzung", "fr": "Comprendre le trafic et l''utilisation du site", "es": "Comprender el tráfico y el uso del sitio web"}},
    {"text_translations": {"en": "To maintain the security and functionality of our website", "de": "Aufrechterhaltung der Sicherheit und Funktionsfähigkeit unserer Website", "fr": "Maintenir la sécurité et le fonctionnement du site", "es": "Mantener la seguridad y funcionalidad del sitio"}},
    {"text_translations": {"en": "To prevent fraud, abuse, or unauthorized activity", "de": "Verhinderung von Betrug, Missbrauch oder unbefugten Aktivitäten", "fr": "Prévenir la fraude, les abus ou les activités non autorisées", "es": "Prevenir fraudes, abusos o actividades no autorizadas"}},
    {"text_translations": {"en": "To comply with legal obligations", "de": "Erfüllung gesetzlicher Verpflichtungen", "fr": "Respecter nos obligations légales", "es": "Cumplir obligaciones legales"}},
    {"text_translations": {"en": "To establish, exercise, or defend legal claims", "de": "Geltendmachung, Ausübung oder Verteidigung rechtlicher Ansprüche", "fr": "Établir, exercer ou défendre des droits en justice", "es": "Establecer, ejercer o defender reclamaciones legales"}}
  ]},
  {"type": "paragraph", "text_translations": {"en": "Where processing is based on your consent, you may withdraw that consent at any time.", "de": "Wenn die Verarbeitung auf Ihrer Einwilligung beruht, können Sie diese jederzeit widerrufen.", "fr": "Lorsque le traitement repose sur votre consentement, vous pouvez retirer ce consentement à tout moment.", "es": "Cuando el tratamiento se base en su consentimiento, puede retirar dicho consentimiento en cualquier momento."}},
  {"type": "heading", "icon": "shield-check", "text_translations": {"en": "4. Legal Bases for Processing", "de": "4. Rechtsgrundlagen der Verarbeitung", "fr": "4. Bases légales du traitement", "es": "4. Bases legales para el tratamiento"}},
  {"type": "paragraph", "text_translations": {"en": "Depending on the circumstances, we process personal information on the following legal bases under applicable data protection law, including the EU General Data Protection Regulation (GDPR):", "de": "Je nach Situation verarbeiten wir personenbezogene Daten auf Grundlage der geltenden Datenschutzgesetze, einschließlich der Datenschutz-Grundverordnung (DSGVO):", "fr": "Selon les circonstances, nous traitons les informations personnelles sur les bases juridiques prévues par la législation applicable en matière de protection des données, notamment le Règlement général sur la protection des données (RGPD) :", "es": "Dependiendo de las circunstancias, tratamos la información personal sobre las siguientes bases legales previstas por la legislación aplicable en materia de protección de datos, incluido el Reglamento General de Protección de Datos (RGPD):"}},
  {"type": "list", "items": [
    {"text_translations": {"en": "Consent — for optional analytics or other processing where consent is required.", "de": "Einwilligung — für optionale Analysen oder andere Verarbeitungsvorgänge, für die eine Einwilligung erforderlich ist.", "fr": "Consentement — pour les analyses facultatives ou tout autre traitement nécessitant un consentement.", "es": "Consentimiento — para análisis opcionales u otros tratamientos que requieran consentimiento."}},
    {"text_translations": {"en": "Contract or steps prior to entering into a contract — when necessary to provide requested services or respond to a service request.", "de": "Vertrag oder vorvertragliche Maßnahmen — wenn dies zur Erbringung angeforderter Dienstleistungen erforderlich ist.", "fr": "Contrat ou mesures précontractuelles — lorsque cela est nécessaire pour fournir les services demandés.", "es": "Contrato o medidas precontractuales — cuando sea necesario para proporcionar servicios solicitados."}},
    {"text_translations": {"en": "Legitimate interests — where necessary to operate, secure, maintain, and improve our services, provided that these interests do not override your rights and freedoms.", "de": "Berechtigte Interessen — wenn dies für den Betrieb, die Sicherheit, die Wartung und Verbesserung unserer Dienstleistungen erforderlich ist und Ihre Rechte und Freiheiten nicht überwiegen.", "fr": "Intérêts légitimes — lorsque cela est nécessaire pour exploiter, sécuriser, maintenir et améliorer nos services, sous réserve que ces intérêts ne prévalent pas sur vos droits et libertés.", "es": "Intereses legítimos — cuando sea necesario para operar, proteger, mantener y mejorar nuestros servicios, siempre que dichos intereses no prevalezcan sobre sus derechos y libertades."}},
    {"text_translations": {"en": "Legal obligation — where processing is required by applicable law.", "de": "Gesetzliche Verpflichtung — wenn die Verarbeitung gesetzlich vorgeschrieben ist.", "fr": "Obligation légale — lorsque le traitement est requis par la loi.", "es": "Obligación legal — cuando el tratamiento sea exigido por la legislación aplicable."}}
  ]},
  {"type": "heading", "icon": "cookie", "text_translations": {"en": "5. Cookies and Tracking Technologies", "de": "5. Cookies und Tracking-Technologien", "fr": "5. Cookies et technologies de suivi", "es": "5. Cookies y tecnologías de seguimiento"}},
  {"type": "paragraph", "text_translations": {"en": "Our website uses cookies and similar technologies for essential functionality, preferences, and, where you provide the appropriate consent, analytics.", "de": "Unsere Website verwendet Cookies und ähnliche Technologien für wesentliche Funktionen, Präferenzen und, sofern Sie die erforderliche Einwilligung erteilen, für Analysezwecke.", "fr": "Notre site utilise des cookies et des technologies similaires pour assurer les fonctionnalités essentielles, mémoriser certaines préférences et, lorsque vous donnez votre consentement approprié, effectuer des analyses.", "es": "Nuestro sitio web utiliza cookies y tecnologías similares para funciones esenciales, preferencias y, cuando proporciona el consentimiento correspondiente, análisis."}},
  {"type": "paragraph", "text_translations": {"en": "Optional analytics tracking is not activated before the required consent is provided.", "de": "Optionales Analytics-Tracking wird nicht aktiviert, bevor die erforderliche Einwilligung erteilt wurde.", "fr": "Le suivi analytique facultatif n''est pas activé avant l''obtention du consentement requis.", "es": "El seguimiento analítico opcional no se activa antes de obtener el consentimiento requerido."}},
  {"type": "paragraph", "text_translations": {"en": "You can change or withdraw your optional cookie preferences at any time through Cookie Settings in the website footer.", "de": "Sie können Ihre optionalen Cookie-Einstellungen jederzeit über Cookie Settings in der Fußzeile unserer Website ändern oder widerrufen.", "fr": "Vous pouvez modifier ou retirer vos préférences à tout moment en sélectionnant Cookie Settings dans le pied de page du site.", "es": "Puede cambiar o retirar sus preferencias de cookies opcionales en cualquier momento seleccionando Cookie Settings en el pie de página del sitio web."}},
  {"type": "paragraph", "text_translations": {"en": "For detailed information about the technologies we use and how to manage your choices, please see our [Cookie Policy](/cookie-policy).", "de": "Weitere Informationen finden Sie in unserer [Cookie-Richtlinie](/cookie-policy).", "fr": "Pour plus d''informations, veuillez consulter notre [Politique de cookies](/cookie-policy).", "es": "Para obtener información detallada, consulte nuestra [Política de Cookies](/cookie-policy)."}},
  {"type": "heading", "icon": "settings", "text_translations": {"en": "6. Google Analytics 4", "de": "6. Google Analytics 4", "fr": "6. Google Analytics 4", "es": "6. Google Analytics 4"}},
  {"type": "paragraph", "text_translations": {"en": "We use Google Analytics 4 (GA4) to understand website traffic and how visitors interact with our website.", "de": "Wir verwenden Google Analytics 4 (GA4), um den Website-Traffic zu verstehen und zu analysieren, wie Besucher mit unserer Website interagieren.", "fr": "Nous utilisons Google Analytics 4 (GA4) afin de comprendre le trafic du site et la manière dont les visiteurs interagissent avec celui-ci.", "es": "Utilizamos Google Analytics 4 (GA4) para comprender el tráfico del sitio web y cómo interactúan los visitantes con nuestro sitio."}},
  {"type": "paragraph", "text_translations": {"en": "GA4 analytics tracking is activated only when the appropriate Analytics consent has been provided through our consent mechanism.", "de": "Das GA4-Tracking wird nur aktiviert, wenn die entsprechende Einwilligung für Analytics erteilt wurde.", "fr": "Le suivi GA4 n''est activé qu''après l''obtention du consentement analytique approprié.", "es": "El seguimiento de GA4 solo se activa cuando se ha proporcionado el consentimiento correspondiente para Analytics."}},
  {"type": "paragraph", "text_translations": {"en": "GA4 may process information relating to website interactions, device and browser characteristics, approximate geographic information, and other measurement data.", "de": "GA4 kann Informationen über Website-Interaktionen, Geräte- und Browsereigenschaften, ungefähre geografische Informationen und andere Messdaten verarbeiten.", "fr": "GA4 peut traiter des informations relatives aux interactions avec le site, aux caractéristiques de l''appareil et du navigateur, à la localisation géographique approximative et à d''autres données de mesure.", "es": "GA4 puede procesar información relacionada con las interacciones con el sitio, las características del dispositivo y navegador, información geográfica aproximada y otros datos de medición."}},
  {"type": "paragraph", "text_translations": {"en": "For users in the European Union, Google states that individual IP addresses are not logged or stored by Google Analytics. IP information may be used to derive coarse geographic information before being discarded.", "de": "Für Nutzer in der Europäischen Union gibt Google an, dass individuelle IP-Adressen von Google Analytics nicht protokolliert oder gespeichert werden. IP-Informationen können verwendet werden, um ungefähre geografische Informationen abzuleiten, bevor sie verworfen werden.", "fr": "Pour les utilisateurs situés dans l''Union européenne, Google indique que les adresses IP individuelles ne sont pas enregistrées ni stockées par Google Analytics. Les informations IP peuvent être utilisées pour déterminer une localisation géographique approximative avant d''être supprimées.", "es": "Para los usuarios de la Unión Europea, Google indica que las direcciones IP individuales no se registran ni almacenan en Google Analytics. La información de IP puede utilizarse para obtener información geográfica aproximada antes de ser descartada."}},
  {"type": "paragraph", "text_translations": {"en": "For further information about Google''s privacy practices, please refer to Google''s privacy documentation.", "de": "Weitere Informationen zu den Datenschutzpraktiken von Google finden Sie in der Datenschutzdokumentation von Google.", "fr": "Pour plus d''informations sur les pratiques de confidentialité de Google, veuillez consulter sa documentation relative à la confidentialité.", "es": "Para obtener más información sobre las prácticas de privacidad de Google, consulte su documentación de privacidad."}},
  {"type": "heading", "icon": "globe", "text_translations": {"en": "7. Vercel Analytics", "de": "7. Vercel Analytics", "fr": "7. Vercel Analytics", "es": "7. Vercel Analytics"}},
  {"type": "paragraph", "text_translations": {"en": "We use Vercel Web Analytics to understand aggregated website usage and performance.", "de": "Wir verwenden Vercel Web Analytics, um aggregierte Informationen über die Nutzung und Leistung unserer Website zu erhalten.", "fr": "Nous utilisons Vercel Web Analytics pour comprendre de manière agrégée l''utilisation et les performances du site.", "es": "Utilizamos Vercel Web Analytics para comprender de forma agregada el uso y el rendimiento del sitio web."}},
  {"type": "paragraph", "text_translations": {"en": "Vercel describes its analytics information as anonymized, statistical, aggregated, and de-identified in its privacy documentation.", "de": "Vercel beschreibt seine Analytics-Informationen in seiner Datenschutzerklärung als anonymisiert, statistisch, aggregiert und de-identifiziert.", "fr": "Vercel décrit les informations analytiques comme anonymisées, statistiques, agrégées et désidentifiées dans sa documentation relative à la confidentialité.", "es": "Vercel describe la información analítica en su documentación de privacidad como anonimizada, estadística, agregada y desidentificada."}},
  {"type": "paragraph", "text_translations": {"en": "Vercel Web Analytics does not rely on traditional cookies for its analytics measurement.", "de": "Vercel Web Analytics verwendet keine herkömmlichen Cookies für seine Web-Analytics-Messungen.", "fr": "Vercel Web Analytics ne repose pas sur des cookies traditionnels pour ses mesures analytiques.", "es": "Vercel Web Analytics no utiliza cookies tradicionales para sus mediciones analíticas."}},
  {"type": "heading", "icon": "globe", "text_translations": {"en": "8. Third-Party Service Providers", "de": "8. Drittanbieter", "fr": "8. Fournisseurs de services tiers", "es": "8. Proveedores de servicios externos"}},
  {"type": "paragraph", "text_translations": {"en": "We may use trusted third-party providers to help operate our website and business.", "de": "Wir können vertrauenswürdige Drittanbieter einsetzen, die uns beim Betrieb unserer Website und unseres Unternehmens unterstützen.", "fr": "Nous pouvons utiliser des prestataires tiers de confiance pour exploiter notre site web et nos activités.", "es": "Podemos utilizar proveedores externos de confianza para ayudarnos a operar nuestro sitio web y nuestro negocio."}},
  {"type": "paragraph", "text_translations": {"en": "These may include:", "de": "Dazu gehören unter anderem:", "fr": "Ils peuvent notamment inclure :", "es": "Estos pueden incluir:"}},
  {"type": "list", "items": [
    {"text_translations": {"en": "Vercel — website hosting, infrastructure, and analytics services.", "de": "Vercel — Hosting, Infrastruktur und Analytics-Dienste.", "fr": "Vercel — hébergement, infrastructure et services d''analyse.", "es": "Vercel — alojamiento, infraestructura y servicios de análisis."}},
    {"text_translations": {"en": "Google — Google Analytics 4 analytics services.", "de": "Google — Google-Analytics-4-Dienste.", "fr": "Google — services Google Analytics 4.", "es": "Google — servicios de Google Analytics 4."}},
    {"text_translations": {"en": "Other service providers necessary to operate our website, communicate with customers, process forms, or provide requested services.", "de": "Weitere Dienstleister, die für den Betrieb unserer Website, die Kommunikation, die Verarbeitung von Formularen oder die Erbringung angeforderter Dienstleistungen erforderlich sind.", "fr": "D''autres prestataires nécessaires au fonctionnement du site, aux communications, au traitement des formulaires ou à la fourniture des services demandés.", "es": "Otros proveedores necesarios para operar nuestro sitio web, comunicarnos con los clientes, procesar formularios o proporcionar los servicios solicitados."}}
  ]},
  {"type": "paragraph", "text_translations": {"en": "We do not sell your personal information.", "de": "Wir verkaufen Ihre personenbezogenen Daten nicht.", "fr": "Nous ne vendons pas vos informations personnelles.", "es": "No vendemos su información personal."}},
  {"type": "heading", "icon": "refresh", "text_translations": {"en": "9. Data Retention", "de": "9. Speicherung und Aufbewahrung", "fr": "9. Conservation des données", "es": "9. Conservación de datos"}},
  {"type": "paragraph", "text_translations": {"en": "We retain personal information only for as long as reasonably necessary for the purposes described in this Privacy Policy, to provide our services, maintain appropriate business records, resolve disputes, enforce agreements, or comply with legal obligations.", "de": "Wir speichern personenbezogene Daten nur so lange, wie dies für die in dieser Datenschutzerklärung beschriebenen Zwecke, die Erbringung unserer Dienstleistungen, geschäftliche Aufzeichnungen, die Beilegung von Streitigkeiten, die Durchsetzung von Vereinbarungen oder die Erfüllung gesetzlicher Verpflichtungen angemessen erforderlich ist.", "fr": "Nous conservons les informations personnelles uniquement pendant la durée raisonnablement nécessaire aux finalités décrites dans cette Politique de confidentialité, à la fourniture de nos services, à la tenue de documents commerciaux, au règlement des litiges, à l''application de nos accords ou au respect des obligations légales.", "es": "Conservamos la información personal únicamente durante el tiempo razonablemente necesario para los fines descritos en esta Política de Privacidad, proporcionar nuestros servicios, mantener registros comerciales, resolver disputas, hacer cumplir acuerdos o cumplir obligaciones legales."}},
  {"type": "paragraph", "text_translations": {"en": "Analytics data may be retained according to the retention settings configured in our analytics services.", "de": "Analytics-Daten können entsprechend den in unseren Analytics-Diensten konfigurierten Aufbewahrungseinstellungen gespeichert werden.", "fr": "Les données analytiques peuvent être conservées conformément aux paramètres de conservation configurés dans nos services d''analyse.", "es": "Los datos analíticos pueden conservarse de acuerdo con la configuración de conservación establecida en nuestros servicios de análisis."}},
  {"type": "heading", "icon": "lock", "text_translations": {"en": "10. Data Security", "de": "10. Datensicherheit", "fr": "10. Sécurité des données", "es": "10. Seguridad de los datos"}},
  {"type": "paragraph", "text_translations": {"en": "We implement appropriate technical and organizational measures designed to protect personal information against unauthorized access, loss, misuse, alteration, or disclosure.", "de": "Wir setzen angemessene technische und organisatorische Maßnahmen ein, um personenbezogene Daten vor unbefugtem Zugriff, Verlust, Missbrauch, Veränderung oder Offenlegung zu schützen.", "fr": "Nous mettons en œuvre des mesures techniques et organisationnelles appropriées destinées à protéger les informations personnelles contre tout accès non autorisé, perte, utilisation abusive, modification ou divulgation.", "es": "Implementamos medidas técnicas y organizativas apropiadas destinadas a proteger la información personal contra el acceso no autorizado, pérdida, uso indebido, modificación o divulgación."}},
  {"type": "paragraph", "text_translations": {"en": "However, no method of transmission or electronic storage is completely secure, and we cannot guarantee absolute security.", "de": "Keine Übertragung über das Internet und keine elektronische Speicherung kann jedoch vollständig sicher garantiert werden.", "fr": "Toutefois, aucune transmission sur Internet ou aucun stockage électronique n''est totalement sécurisé.", "es": "Sin embargo, ningún método de transmisión por Internet o almacenamiento electrónico es completamente seguro."}},
  {"type": "heading", "icon": "clipboard-check", "text_translations": {"en": "11. Your Privacy Rights", "de": "11. Ihre Rechte", "fr": "11. Vos droits", "es": "11. Sus derechos"}},
  {"type": "paragraph", "text_translations": {"en": "Depending on applicable law, including the GDPR where applicable, you may have rights including:", "de": "Je nach geltendem Recht, insbesondere nach der DSGVO, können Sie folgende Rechte haben:", "fr": "Selon la législation applicable, notamment le RGPD, vous pouvez disposer des droits suivants :", "es": "Dependiendo de la legislación aplicable, incluido el RGPD, puede tener los siguientes derechos:"}},
  {"type": "list", "items": [
    {"text_translations": {"en": "The right to access your personal data", "de": "Recht auf Auskunft", "fr": "Droit d''accès à vos données personnelles", "es": "Derecho de acceso a sus datos personales"}},
    {"text_translations": {"en": "The right to correct inaccurate or incomplete data", "de": "Recht auf Berichtigung", "fr": "Droit de rectification", "es": "Derecho de rectificación"}},
    {"text_translations": {"en": "The right to request deletion of your personal data", "de": "Recht auf Löschung", "fr": "Droit à l''effacement", "es": "Derecho de supresión"}},
    {"text_translations": {"en": "The right to restrict certain processing", "de": "Recht auf Einschränkung der Verarbeitung", "fr": "Droit à la limitation du traitement", "es": "Derecho a limitar el tratamiento"}},
    {"text_translations": {"en": "The right to object to certain processing", "de": "Recht auf Widerspruch", "fr": "Droit d''opposition", "es": "Derecho de oposición"}},
    {"text_translations": {"en": "The right to data portability", "de": "Recht auf Datenübertragbarkeit", "fr": "Droit à la portabilité des données", "es": "Derecho a la portabilidad de los datos"}},
    {"text_translations": {"en": "The right to withdraw consent where processing is based on consent", "de": "Recht auf Widerruf einer Einwilligung, wenn die Verarbeitung darauf beruht", "fr": "Droit de retirer votre consentement lorsque le traitement repose sur celui-ci", "es": "Derecho a retirar el consentimiento cuando el tratamiento se base en este"}}
  ]},
  {"type": "paragraph", "text_translations": {"en": "You can exercise applicable rights by contacting us at [privacy@stratifit.com](mailto:privacy@stratifit.com).", "de": "Zur Ausübung Ihrer Rechte kontaktieren Sie uns unter [privacy@stratifit.com](mailto:privacy@stratifit.com).", "fr": "Pour exercer vos droits, contactez-nous à [privacy@stratifit.com](mailto:privacy@stratifit.com).", "es": "Para ejercer sus derechos, puede ponerse en contacto con nosotros en [privacy@stratifit.com](mailto:privacy@stratifit.com)."}},
  {"type": "paragraph", "text_translations": {"en": "You also have the right to lodge a complaint with a competent data protection supervisory authority.", "de": "Sie haben außerdem das Recht, sich bei einer zuständigen Datenschutzaufsichtsbehörde zu beschweren.", "fr": "Vous avez également le droit d''introduire une réclamation auprès d''une autorité de contrôle compétente.", "es": "También tiene derecho a presentar una reclamación ante una autoridad de protección de datos competente."}},
  {"type": "heading", "icon": "shield-check", "text_translations": {"en": "12. Children''s Privacy", "de": "12. Datenschutz von Kindern", "fr": "12. Protection des enfants", "es": "12. Privacidad de los menores"}},
  {"type": "paragraph", "text_translations": {"en": "Our website and services are not specifically directed at children. We do not knowingly collect personal information from children where such collection is prohibited by applicable law.", "de": "Unsere Website und Dienstleistungen richten sich nicht speziell an Kinder. Wir erheben nicht wissentlich personenbezogene Daten von Kindern, soweit deren Erhebung nach geltendem Recht unzulässig ist.", "fr": "Notre site et nos services ne sont pas spécifiquement destinés aux enfants. Nous ne collectons pas sciemment de données personnelles d''enfants lorsque leur collecte est interdite par la législation applicable.", "es": "Nuestro sitio web y nuestros servicios no están dirigidos específicamente a menores. No recopilamos conscientemente información personal de menores cuando dicha recopilación esté prohibida por la legislación aplicable."}},
  {"type": "heading", "icon": "globe", "text_translations": {"en": "13. International Data Transfers", "de": "13. Internationale Datenübermittlungen", "fr": "13. Transferts internationaux de données", "es": "13. Transferencias internacionales de datos"}},
  {"type": "paragraph", "text_translations": {"en": "Some of our service providers may process information in countries outside your country of residence.", "de": "Einige unserer Dienstleister können Informationen in Ländern außerhalb Ihres Wohnsitzlandes verarbeiten.", "fr": "Certains de nos prestataires peuvent traiter des informations dans des pays situés en dehors de votre pays de résidence.", "es": "Algunos de nuestros proveedores de servicios pueden procesar información en países situados fuera de su país de residencia."}},
  {"type": "paragraph", "text_translations": {"en": "Where personal information is transferred internationally, we rely on appropriate safeguards required by applicable data protection law.", "de": "Bei internationalen Übermittlungen personenbezogener Daten verwenden wir die nach geltendem Datenschutzrecht erforderlichen geeigneten Schutzmaßnahmen.", "fr": "Lorsque des données personnelles sont transférées à l''international, nous mettons en place les garanties appropriées requises par la législation applicable.", "es": "Cuando se transfieren datos personales internacionalmente, utilizamos las garantías adecuadas exigidas por la legislación aplicable en materia de protección de datos."}},
  {"type": "heading", "icon": "refresh", "text_translations": {"en": "14. Changes to This Privacy Policy", "de": "14. Änderungen dieser Datenschutzerklärung", "fr": "14. Modifications de cette Politique de confidentialité", "es": "14. Cambios en esta Política de Privacidad"}},
  {"type": "paragraph", "text_translations": {"en": "We may update this Privacy Policy from time to time to reflect changes to our services, technologies, data practices, or legal requirements.", "de": "Wir können diese Datenschutzerklärung von Zeit zu Zeit aktualisieren, um Änderungen unserer Dienstleistungen, Technologien, Datenverarbeitungspraktiken oder gesetzlichen Anforderungen zu berücksichtigen.", "fr": "Nous pouvons mettre à jour cette Politique de confidentialité afin de refléter les changements concernant nos services, technologies, pratiques de traitement des données ou obligations légales.", "es": "Podemos actualizar esta Política de Privacidad periódicamente para reflejar cambios en nuestros servicios, tecnologías, prácticas de tratamiento de datos o requisitos legales."}},
  {"type": "paragraph", "text_translations": {"en": "When we make changes, we will update the Last updated date on this page.", "de": "Bei Änderungen wird das Datum der letzten Aktualisierung angepasst.", "fr": "La date de mise à jour sera modifiée lorsque des changements seront apportés.", "es": "Cuando realicemos cambios, actualizaremos la fecha de Última actualización de esta página."}},
  {"type": "paragraph", "text_translations": {"en": "We encourage you to review this Privacy Policy periodically.", "de": "Wir empfehlen Ihnen, diese Datenschutzerklärung regelmäßig zu überprüfen.", "fr": "Nous vous encourageons à consulter régulièrement cette Politique de confidentialité.", "es": "Le recomendamos revisar periódicamente esta Política de Privacidad."}},
  {"type": "subheading", "divider": true, "text_translations": {"en": "Contact Us", "de": "Kontakt", "fr": "Contact", "es": "Contacto"}},
  {"type": "paragraph", "text_translations": {"en": "Stratifit", "de": "Stratifit", "fr": "Stratifit", "es": "Stratifit"}},
  {"type": "paragraph", "text_translations": {"en": "Email: [privacy@stratifit.com](mailto:privacy@stratifit.com)", "de": "E-Mail: [privacy@stratifit.com](mailto:privacy@stratifit.com)", "fr": "E-mail : [privacy@stratifit.com](mailto:privacy@stratifit.com)", "es": "Correo electrónico: [privacy@stratifit.com](mailto:privacy@stratifit.com)"}},
  {"type": "paragraph", "text_translations": {"en": "Website: [https://stratifit.com](https://stratifit.com)", "de": "Website: [https://stratifit.com](https://stratifit.com)", "fr": "Site web : [https://stratifit.com](https://stratifit.com)", "es": "Sitio web: [https://stratifit.com](https://stratifit.com)"}}
